    /// One List.cons cell: `List.cons (Char.ofNat c) tail`.
    fn char_cons(c: u64, tail: Expr) -> Expr {
        let char_val = Expr::app(Expr::cnst(nm_char_ofnat()), Expr::nat(c));
        Expr::app(Expr::app(Expr::cnst(nm_list_cons()), char_val), tail)
    }
    /// A two-Char list `[Char.ofNat c0, Char.ofNat c1]` built right-to-left over
    /// List.nil.
    fn char_list_2(c0: u64, c1: u64) -> Expr {
        char_cons(c0, char_cons(c1, Expr::cnst(nm_list_nil())))
    }

    /// R12 — tc/reduction/nat.rs:357-394 string_lit_to_constructor, VERBATIM in
    /// shape (String.ofList over the right-to-left List.cons/Char.ofNat chain
    /// terminated by List.nil): builds `String.ofList (List.cons (Char.ofNat c0)
    /// (List.cons (Char.ofNat c1) List.nil))`.
    /// [B-strtag]: the modeled Literal::Str is a u32 TAG (the R11 model); the
    /// codepoints are selected by the tag (tag 0 = "ab" = [97,98], tag 1 = "ac" =
    /// [97,99]) in place of the production `for c in s.chars().rev()` over an
    /// `Arc<str>` — ASCII, so the production char decode equals the byte; the
    /// right-to-left build is preserved. The `Arc<str>` Literal + `chars()`
    /// decode is the frontend string-shape gap (round-3/4 ledger; same class as
    /// `format_args!` / runtime `split` — a byte-string/`&[u8]` constant does not
    /// lower as a single scalar).
    fn string_lit_to_constructor(tag: u32) -> Expr {
        let list = if tag == 0 {
            char_list_2(97, 98)
        } else if tag == 1 {
            char_list_2(97, 99)
        } else {
            Expr::cnst(nm_list_nil())
        };
        Expr::app(Expr::cnst(nm_str_oflist()), list)
    }

    /// The String.mk constructor form the expansion normalises to, for the P7
    /// scenario RHS: `String.mk [Char.ofNat c0, Char.ofNat c1]`.
    fn string_mk_form_ab() -> Expr {
        Expr::app(Expr::cnst(nm_str_mk()), char_list_2(97, 98))
    }
    fn string_mk_form_ac() -> Expr {
        Expr::app(Expr::cnst(nm_str_mk()), char_list_2(97, 99))
    }

    // ════════════════════════════════════════════════════════════════════════════
    // IN-MODULE SCENARIOS — the landed T1 case set (same universe coverage, same
