// ════════════════════════════════════════════════════════════════════════════
// Native oracles (independent of the slice/mirror code paths).
// ════════════════════════════════════════════════════════════════════════════

/// clean-kernel expr/meta.rs mix_hash — VERBATIM.
fn native_mix_hash(h: u64, k: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let mut k = k.wrapping_mul(M);
    k ^= k >> R;
    k ^= M;
    let h = h ^ k;
    h.wrapping_mul(M)
}

/// clean-kernel murmur_hash_64a in the PRODUCTION block form (as-chunks ≡
/// chunks_exact(8) + remainder) — the modules carry the index-loop
/// transcription, so agreement proves [T-murmur-idx] on every tested name.
fn native_murmur_hash_64a(data: &[u8], seed: u64) -> u64 {
    const M: u64 = 0xc6a4_a793_5bd1_e995;
    const R: u32 = 47;
    let len = data.len();
    let mut h: u64 = seed ^ (len as u64).wrapping_mul(M);
    let mut chunks = data.chunks_exact(8);
    for block in &mut chunks {
        let mut k = u64::from_le_bytes(block.try_into().expect("8-byte chunk"));
        k = k.wrapping_mul(M);
        k ^= k >> (R & 63);
        k = k.wrapping_mul(M);
        h ^= k;
        h = h.wrapping_mul(M);
    }
    let tail = chunks.remainder();
    for (i, &b) in tail.iter().enumerate() {
        h ^= (b as u64) << (i.wrapping_mul(8) & 63);
    }
    if !tail.is_empty() {
        h = h.wrapping_mul(M);
    }
    h ^= h >> (R & 63);
    h = h.wrapping_mul(M);
    h ^= h >> (R & 63);
    h
}

/// A decoded Name component, leaf-to-root.
#[derive(Debug, Clone, PartialEq, Eq)]
enum Comp {
    Str(Vec<u8>),
    Num(u64),
}

// GOLDEN constants from the REAL clean-kernel binary (pinned in R4-R6; see
// e2e_universe_realnames.rs module docs for the pin recipe).
const GOLDEN_U: u64 = 0xae572a66f1f7b2e8;
#[allow(dead_code)] // R10 pin, kept for cross-round reference
const GOLDEN_V: u64 = 0x486e7075aebc6ca6;
#[allow(dead_code)] // R10 pin, kept for cross-round reference
const GOLDEN_NAT: u64 = 0x9ecc0d3a68dfdd9b;
const GOLDEN_AX_DUP: u64 = 0xfdb31ca9d0ac3c36;
#[allow(dead_code)] // R10 pin, kept for cross-round reference
const GOLDEN_THM42: u64 = 0xdcaef40c027c85c5;
const GOLDEN_ANON: u64 = 1723;

// ── the JIT-side raw Name decode (offsets identical to rounds 4-8) ──────────

/// Walk a JIT-built Name at `ptr`: returns (leaf-to-root comps, root hash,
/// per-node hashes leaf-to-root). Panics on an unknown tag (fail-loud decode).
unsafe fn decode_jit_name(ptr: *const u8) -> (Vec<Comp>, u64, Vec<u64>) {
    unsafe {
        let mut comps = Vec::new();
        let mut node_hashes = Vec::new();
        let read_u64 = |p: *const u8| -> u64 { (p as *const u64).read_unaligned() };
        let read_ptr = |p: *const u8| -> *const u8 { (p as *const *const u8).read_unaligned() };
        let root_hash = read_u64(ptr.add(32));
        let mut cur = ptr;
        loop {
            let tag = read_u64(cur);
            node_hashes.push(read_u64(cur.add(32)));
            match tag {
                0 => break,
                1 => {
                    let parent_inner = read_ptr(cur.add(8));
                    let s_inner = read_ptr(cur.add(16));
                    let s_len = read_u64(cur.add(24)) as usize;
                    let bytes = std::slice::from_raw_parts(s_inner.add(16), s_len).to_vec();
                    comps.push(Comp::Str(bytes));
                    cur = parent_inner.add(16);
                }
                2 => {
                    let n = read_u64(cur.add(8));
                    let parent_inner = read_ptr(cur.add(16));
                    comps.push(Comp::Num(n));
                    cur = parent_inner.add(16);
                }
                t => panic!("decode_jit_name: unknown NameInner tag {t} (layout drift?)"),
            }
        }
        (comps, root_hash, node_hashes)
    }
}

/// Recompute the production hash chain from decoded comps (leaf-to-root):
/// per-node hashes leaf-to-root INCLUDING the final Anon node (1723).
fn recompute_hash_chain(comps: &[Comp]) -> Vec<u64> {
    let mut fwd = vec![1723u64];
    for c in comps.iter().rev() {
        let prev = *fwd.last().unwrap();
        let h = match c {
            Comp::Str(b) => native_mix_hash(prev, native_murmur_hash_64a(b, 11)),
            Comp::Num(n) => native_mix_hash(prev, *n),
        };
        fwd.push(h);
    }
    fwd.reverse();
    fwd
}

/// SAFE walk of a HOST-built (mirror) Name: (leaf-to-root comps, root hash).
fn native_name_comps(n: &rn::Name) -> (Vec<Comp>, u64) {
    let mut comps = Vec::new();
    let mut cur = n;
    loop {
        match &cur.inner {
            rn::NameInner::Anon => break,
            rn::NameInner::Str(p, s) => {
                comps.push(Comp::Str(s.as_bytes().to_vec()));
                cur = &**p;
            }
            rn::NameInner::Num(p, v) => {
                comps.push(Comp::Num(*v));
                cur = &**p;
            }
        }
    }
    (comps, n.cached_hash)
}

// ════════════════════════════════════════════════════════════════════════════
// The asymmetric deep comparators (R6/R8 pattern): native side walked SAFELY
// via mirror types, JIT side Names decoded RAW with the per-node hash chain
// REVALIDATED on every comparison. Meta words compared bit-exact per node.
// ════════════════════════════════════════════════════════════════════════════

fn name_eq_nj(native: &rn::Name, jit: &rn::Name) -> bool {
    let (ncomps, nhash) = native_name_comps(native);
    let (jcomps, jhash, jchain) = unsafe { decode_jit_name(jit as *const rn::Name as *const u8) };
    let expect_chain = recompute_hash_chain(&jcomps);
    assert_eq!(
        jchain, expect_chain,
        "JIT Name per-node hash chain != production recompute (layout drift or hash bug?)"
    );
    ncomps == jcomps && nhash == jhash
}

fn level_eq_nj(native: &rn::Level, jit: &rn::Level) -> bool {
    match (native, jit) {
        (rn::Level::Zero, rn::Level::Zero) => true,
        (rn::Level::Succ(a), rn::Level::Succ(b)) => level_eq_nj(a, b),
        (rn::Level::Max(a1, b1), rn::Level::Max(a2, b2)) => {
            level_eq_nj(a1, a2) && level_eq_nj(b1, b2)
        }
        (rn::Level::IMax(a1, b1), rn::Level::IMax(a2, b2)) => {
            level_eq_nj(a1, a2) && level_eq_nj(b1, b2)
        }
        (rn::Level::Param(a), rn::Level::Param(b)) => name_eq_nj(a, b),
        _ => false,
    }
}

fn levels_eq_nj(native: &[rn::Level], jit: &[rn::Level]) -> bool {
    if native.len() != jit.len() {
        return false;
    }
    native
        .iter()
        .zip(jit.iter())
        .all(|(a, b)| level_eq_nj(a, b))
}

/// Deep native==JIT comparison: meta word BIT-IDENTICAL at every node, then
/// structural with production-name comparison at every Name site. FVar nodes
/// compare by id — the context-discipline observable.
fn deep_eq_nj(native: &rn::Expr, jit: &rn::Expr) -> bool {
    if native.meta.raw() != jit.meta.raw() {
        return false;
    }
    match (&native.kind, &jit.kind) {
        (rn::ExprKind::BVar(x), rn::ExprKind::BVar(y)) => x == y,
        (rn::ExprKind::FVar(x), rn::ExprKind::FVar(y)) => x == y,
        (rn::ExprKind::Lit(x), rn::ExprKind::Lit(y)) => x == y,
        (rn::ExprKind::Sort(x), rn::ExprKind::Sort(y)) => level_eq_nj(x, y),
        (rn::ExprKind::Const(n1, l1), rn::ExprKind::Const(n2, l2)) => {
            name_eq_nj(n1, n2) && levels_eq_nj(l1, l2)
        }
        (rn::ExprKind::App(f1, a1), rn::ExprKind::App(f2, a2)) => {
            deep_eq_nj(f1, f2) && deep_eq_nj(a1, a2)
        }
        (rn::ExprKind::Lam(b1, t1, y1), rn::ExprKind::Lam(b2, t2, y2)) => {
            b1 == b2 && deep_eq_nj(t1, t2) && deep_eq_nj(y1, y2)
        }
        (rn::ExprKind::Pi(b1, t1, y1), rn::ExprKind::Pi(b2, t2, y2)) => {
            b1 == b2 && deep_eq_nj(t1, t2) && deep_eq_nj(y1, y2)
        }
        (rn::ExprKind::Let(n1, t1, v1, y1, d1), rn::ExprKind::Let(n2, t2, v2, y2, d2)) => {
            name_eq_nj(n1, n2)
                && deep_eq_nj(t1, t2)
                && deep_eq_nj(v1, v2)
                && deep_eq_nj(y1, y2)
                && d1 == d2
        }
        (rn::ExprKind::Proj(n1, i1, e1), rn::ExprKind::Proj(n2, i2, e2)) => {
            name_eq_nj(n1, n2) && i1 == i2 && deep_eq_nj(e1, e2)
        }
        (rn::ExprKind::MData(m1, e1), rn::ExprKind::MData(m2, e2)) => {
            m1 == m2 && deep_eq_nj(e1, e2)
        }
        _ => false,
    }
}

fn type_error_disc(e: &rn::TypeError) -> u8 {
    match e {
        rn::TypeError::UnboundVariable(_) => 0,
        rn::TypeError::UnknownFVar(_) => 1,
        rn::TypeError::UnknownConst(_) => 2,
        rn::TypeError::TypeMismatch { .. } => 3,
        rn::TypeError::NotAPi { .. } => 4,
        rn::TypeError::ExpectedSort { .. } => 5,
        rn::TypeError::SortDepthExceeded { .. } => 6,
        rn::TypeError::Unsupported => 7,
    }
}

/// Payload-deep agreement between a native TypeError and a JIT TypeError.
fn type_error_agrees_nj(n: &rn::TypeError, j: &rn::TypeError) -> bool {
    if type_error_disc(n) != type_error_disc(j) {
        return false;
    }
    match (n, j) {
        (rn::TypeError::UnboundVariable(a), rn::TypeError::UnboundVariable(b)) => a == b,
        (rn::TypeError::UnknownFVar(a), rn::TypeError::UnknownFVar(b)) => a == b,
        (rn::TypeError::UnknownConst(a), rn::TypeError::UnknownConst(b)) => name_eq_nj(a, b),
        (
            rn::TypeError::TypeMismatch {
                expected: e1,
                inferred: i1,
            },
            rn::TypeError::TypeMismatch {
                expected: e2,
                inferred: i2,
            },
        ) => deep_eq_nj(e1, e2) && deep_eq_nj(i1, i2),
        (rn::TypeError::NotAPi { ty: t1 }, rn::TypeError::NotAPi { ty: t2 }) => deep_eq_nj(t1, t2),
        (rn::TypeError::ExpectedSort { ty: t1 }, rn::TypeError::ExpectedSort { ty: t2 }) => {
            deep_eq_nj(t1, t2)
        }
        (
            rn::TypeError::SortDepthExceeded { depth: a },
            rn::TypeError::SortDepthExceeded { depth: b },
        ) => a == b,
        _ => true,
    }
}

fn env_error_disc(e: &rn::EnvError) -> u8 {
    match e {
        rn::EnvError::TypeCheckFailed { .. } => 0,
        rn::EnvError::DuplicateLevelParam { .. } => 1,
        rn::EnvError::TheoremTypeNotProp { .. } => 2,
        rn::EnvError::ContainsFreeVar { .. } => 3,
        rn::EnvError::ContainsMetavar { .. } => 4,
        rn::EnvError::UndefinedLevelParam { .. } => 5,
    }
}

/// Payload-deep agreement between the native gate error and the JIT gate
/// error (the R6/R8 comparator).
fn env_error_agrees_nj(n: &rn::EnvError, j: &rn::EnvError) -> bool {
    if env_error_disc(n) != env_error_disc(j) {
        return false;
    }
    match (n, j) {
        (
            rn::EnvError::TypeCheckFailed {
                name: n1,
                source: s1,
            },
            rn::EnvError::TypeCheckFailed {
                name: n2,
                source: s2,
            },
        ) => name_eq_nj(n1, n2) && type_error_agrees_nj(s1, s2),
        (
            rn::EnvError::DuplicateLevelParam {
                name: n1,
                param: p1,
            },
            rn::EnvError::DuplicateLevelParam {
                name: n2,
                param: p2,
            },
        ) => name_eq_nj(n1, n2) && name_eq_nj(p1, p2),
        (
            rn::EnvError::TheoremTypeNotProp { name: n1, sort: s1 },
            rn::EnvError::TheoremTypeNotProp { name: n2, sort: s2 },
        ) => name_eq_nj(n1, n2) && level_eq_nj(s1, s2),
        (
            rn::EnvError::ContainsFreeVar { name: n1 },
            rn::EnvError::ContainsFreeVar { name: n2 },
        ) => name_eq_nj(n1, n2),
        (
            rn::EnvError::ContainsMetavar { name: n1 },
            rn::EnvError::ContainsMetavar { name: n2 },
        ) => name_eq_nj(n1, n2),
        (
            rn::EnvError::UndefinedLevelParam {
                name: n1,
                param: p1,
            },
            rn::EnvError::UndefinedLevelParam {
                name: n2,
                param: p2,
            },
        ) => name_eq_nj(n1, n2) && name_eq_nj(p1, p2),
        _ => false,
    }
}

// ── drivers ──────────────────────────────────────────────────────────────────

type LdGateFn = extern "C" fn(*mut Result<(), rn::EnvError>, *mut rn::Expr, u64);
type PcProbeFn = extern "C" fn(*mut Result<rn::Expr, rn::TypeError>, *mut rn::ProbeIds, u64);

fn jit_gate(f: LdGateFn, case: u64) -> (Result<(), rn::EnvError>, rn::Expr) {
    let mut res_slot = std::mem::MaybeUninit::<Result<(), rn::EnvError>>::uninit();
    let mut ty_slot = std::mem::MaybeUninit::<rn::Expr>::uninit();
    unsafe {
        f(res_slot.as_mut_ptr(), ty_slot.as_mut_ptr(), case);
        (res_slot.assume_init(), ty_slot.assume_init())
    }
}

fn native_gate(case: u64) -> (Result<(), rn::EnvError>, rn::Expr) {
    let mut res_slot = std::mem::MaybeUninit::<Result<(), rn::EnvError>>::uninit();
    let mut ty_slot = std::mem::MaybeUninit::<rn::Expr>::uninit();
    unsafe {
        rn::ld_gate_root(res_slot.as_mut_ptr(), ty_slot.as_mut_ptr(), case);
        (res_slot.assume_init(), ty_slot.assume_init())
    }
}

fn jit_probe(f: PcProbeFn, idx: u64) -> (Result<rn::Expr, rn::TypeError>, rn::ProbeIds) {
    let mut res_slot = std::mem::MaybeUninit::<Result<rn::Expr, rn::TypeError>>::uninit();
    let mut ids_slot = std::mem::MaybeUninit::<rn::ProbeIds>::uninit();
    unsafe {
        f(res_slot.as_mut_ptr(), ids_slot.as_mut_ptr(), idx);
        (res_slot.assume_init(), ids_slot.assume_init())
    }
}

fn native_probe(idx: u64) -> (Result<rn::Expr, rn::TypeError>, rn::ProbeIds) {
    let mut res_slot = std::mem::MaybeUninit::<Result<rn::Expr, rn::TypeError>>::uninit();
    let mut ids_slot = std::mem::MaybeUninit::<rn::ProbeIds>::uninit();
    unsafe {
        rn::pc_probe_root(res_slot.as_mut_ptr(), ids_slot.as_mut_ptr(), idx);
        (res_slot.assume_init(), ids_slot.assume_init())
    }
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 1 — module sanity: both fixtures parse + validate 0; the four completed
// phases are genuinely IN-MODULE and WIRED at their production positions
// (is_def_eq_core -> is_def_eq_structural / try_string_lit_expansion /
// is_def_eq_unit_like / is_bool_true_const; is_def_eq_structural ->
// try_structure_eta_expansion -> try_structure_eta_core -> get_constructor /
// is_structure_like -> get_inductive). The R11-config engine (is_def_eq_core_r11)
// routes P6 through is_def_eq_structural_nostruct -> try_structure_eta_expansion_stub
// and ELIDES reflection / P7 / P8 (no edges) — the divergence is structural.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn pc_module_sanity_and_inmodule_surface() {
    let shared_syms = [
        "LocalContext__new",
        "LocalContext__push",
        "LocalContext__get",
        "Expr__instantiate",
        "name_anon",
        "name_str_part",
        "name_eq",
        "ExprKind__compute_meta",
        "expr_syntactic_eq",
    ];
    for (text, what) in [
        (PC_PROBE_TRUST_IR, "pc_probe_root closure"),
        (PC_GATE_TRUST_IR, "ld_gate_root closure"),
    ] {
        let module = parse_and_validate(text, what);
        let bodied = |sym: &str| {
            module
                .functions
                .iter()
                .find(|f| f.name == sym)
                .map(|f| !f.blocks.is_empty())
                .unwrap_or(false)
        };
        for sym in shared_syms {
            assert!(
                bodied(sym),
                "`{sym}` must be lowered in-module (bodied) in {what}"
            );
        }
    }

    let idx_of = |module: &trust_ir::Module, sym: &str| -> usize {
        module
            .functions
            .iter()
            .position(|f| f.name == sym)
            .unwrap_or_else(|| panic!("`{sym}` not in module"))
    };
    let body_of = |text: &'static str, sym: &str| -> &'static str {
        let start = text
            .find(&format!("fn @{sym}("))
            .unwrap_or_else(|| panic!("`{sym}` header present in IR text"));
        let after = &text[start + 1..];
        let end = after
            .find("\nfn @")
            .map(|i| start + 1 + i)
            .unwrap_or(text.len());
        &text[start..end]
    };
    let edge = |text: &'static str, module: &trust_ir::Module, caller: &str, callee: &str| {
        let b = body_of(text, caller);
        let i = idx_of(module, callee);
        assert!(
            b.contains(&format!("@func.{i}(")),
            "`{caller}` must Call @func.{i} = `{callee}` — the composition edge must RUN"
        );
    };
    let no_edge = |text: &'static str, module: &trust_ir::Module, caller: &str, callee: &str| {
        let b = body_of(text, caller);
        let i = idx_of(module, callee);
        assert!(
            !b.contains(&format!("@func.{i}(")),
            "`{caller}` must NOT call `{callee}`"
        );
    };

    let module = parse_and_validate(PC_PROBE_TRUST_IR, "pc_probe_root closure");
    let bodied = |sym: &str| {
        module
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    for sym in [
        // the four completed phases + the registry consults:
        "Verifier____env___is_def_eq_core",
        "Verifier____env___is_def_eq_structural",
        "Verifier____env___try_structure_eta_expansion",
        "Verifier____env___try_structure_eta_core",
        "Verifier____env___is_structure_like",
        "Verifier____env___get_constructor",
        "Verifier____env___get_inductive",
        "Verifier____env___try_string_lit_expansion",
        "Verifier____env___try_string_lit_expansion_core",
        "Verifier____env___is_def_eq_unit_like",
        "is_bool_true_const",
        "string_lit_to_constructor",
        // the R11-config divergence engine:
        "Verifier____env___is_def_eq_r11",
        "Verifier____env___is_def_eq_core_r11",
        "Verifier____env___is_def_eq_structural_nostruct",
        "Verifier____env___try_structure_eta_expansion_stub",
        // the R11 phase engine, re-confirmed:
        "Verifier____env___is_def_eq",
        "Verifier____env___quick_is_def_eq",
        "Verifier____env___lazy_delta_reduction",
        "Verifier____env___whnf_inner",
        "Verifier____env___is_def_eq_proof_irrel",
        "pc_probe_root",
    ] {
        assert!(bodied(sym), "`{sym}` must be lowered in-module (bodied)");
    }

    // THE FOUR PHASES WIRED AT THEIR PRODUCTION POSITIONS (R12 engine):
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_core",
        "Verifier____env___is_def_eq_structural",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_core",
        "Verifier____env___try_string_lit_expansion",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_core",
        "Verifier____env___is_def_eq_unit_like",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_core",
        "is_bool_true_const",
    );
    // struct-eta chain into the registry:
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_structural",
        "Verifier____env___try_structure_eta_expansion",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___try_structure_eta_expansion",
        "Verifier____env___try_structure_eta_core",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___try_structure_eta_core",
        "Verifier____env___get_constructor",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___try_structure_eta_core",
        "Verifier____env___is_structure_like",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_structure_like",
        "Verifier____env___get_inductive",
    );
    // unit-like consults the registry:
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_unit_like",
        "Verifier____env___get_inductive",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_unit_like",
        "Verifier____env___get_constructor",
    );
    // string-lit expands then reduces:
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___try_string_lit_expansion",
        "Verifier____env___try_string_lit_expansion_core",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___try_string_lit_expansion_core",
        "string_lit_to_constructor",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___try_string_lit_expansion_core",
        "Verifier____env___whnf_impl",
    );
    // reflection uses the FULL whnf (unfolds theorems) — the #3305 lever:
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___whnf_inner",
        "Verifier____env___unfold_definition_model",
    );

    // THE R11-CONFIG DIVERGENCE IS STRUCTURAL: P6 -> nostruct -> the false stub,
    // and reflection / P7 / P8 are ABSENT from the R11 core.
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_core_r11",
        "Verifier____env___is_def_eq_structural_nostruct",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_structural_nostruct",
        "Verifier____env___try_structure_eta_expansion_stub",
    );
    no_edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_core_r11",
        "Verifier____env___try_string_lit_expansion",
    );
    no_edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_core_r11",
        "Verifier____env___is_def_eq_unit_like",
    );
    no_edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_core_r11",
        "is_bool_true_const",
    );
    no_edge(
        PC_PROBE_TRUST_IR,
        &module,
        "Verifier____env___is_def_eq_structural_nostruct",
        "Verifier____env___try_structure_eta_expansion",
    );

    // the probe root drives BOTH engines + the real phase helpers directly:
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "pc_probe_root",
        "Verifier____env___is_def_eq",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "pc_probe_root",
        "Verifier____env___is_def_eq_r11",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "pc_probe_root",
        "Verifier____env___try_structure_eta_expansion",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "pc_probe_root",
        "Verifier____env___is_def_eq_unit_like",
    );
    edge(
        PC_PROBE_TRUST_IR,
        &module,
        "pc_probe_root",
        "Verifier____env___try_string_lit_expansion",
    );

    // the gate module runs the SAME completed engine (is_def_eq_core with all
    // four phases) — the 28-case re-run goes through the phase-completed def_eq.
    let gmodule = parse_and_validate(PC_GATE_TRUST_IR, "ld_gate_root closure");
    let gbodied = |sym: &str| {
        gmodule
            .functions
            .iter()
            .find(|f| f.name == sym)
            .map(|f| !f.blocks.is_empty())
            .unwrap_or(false)
    };
    for sym in [
        "Verifier____env___check_decl_readonly",
        "Verifier____env___is_def_eq_core",
        "Verifier____env___try_string_lit_expansion",
        "Verifier____env___is_def_eq_unit_like",
        "Verifier____env___try_structure_eta_expansion",
        "ld_gate_root",
    ] {
        assert!(
            gbodied(sym),
            "`{sym}` must be lowered in-module (bodied) in the gate fixture"
        );
    }
    edge(
        PC_GATE_TRUST_IR,
        &gmodule,
        "Verifier____env___is_def_eq_core",
        "Verifier____env___try_string_lit_expansion",
    );
    edge(
        PC_GATE_TRUST_IR,
        &gmodule,
        "Verifier____env___is_def_eq_core",
        "Verifier____env___is_def_eq_unit_like",
    );
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 2 — THE FOUR PHASES, native == JIT at full payload depth. Each idx's
// flags encode: (bit set = condition holds) the R12 accept, the R11-config
// DIVERGENCE (reject), the real-vs-stub helper split, the earlier-phase
// no-decision witnesses (phase attribution), and the poisoned-registry flip.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn pc_phase_completion_differential() {
    let buffer = run_with_watchdog("JIT compile pc_probe_root", move || {
        jit_module(PC_PROBE_TRUST_IR, "pc_probe_root closure", &pc_externs())
    });
    let probe: PcProbeFn = unsafe { std::mem::transmute(bind(&buffer, "pc_probe_root")) };

    let labels: [&str; 4] = [
        "STRUCT-ETA (P6): eta ctor-app =?= fvar; R11 false-stub rejects; recursive-struct poison rejects",
        "BOOL.TRUE REFLECTION: theorem(:=Bool.true) =?= Bool.true; R11 rejects; #3305 lazy-delta Err; value/name/fvar controls",
        "UNIT-LIKE (P8): two PUnit fvars; R11 rejects; proof-irrel inert (Type); Cell/Bool reject",
        "STRING-LIT (P7): \"ab\" =?= String.mk[..]; R11 rejects; unequal/two-lit/poisoned-ofList reject",
    ];
    // Pinned native expectations (ALL divergence + attribution + poison bits set).
    let expect_flags: [u64; 4] = [127, 255, 127, 127];

    for idx in 0u64..4 {
        let label = labels[idx as usize];
        let (nres, nids) = native_probe(idx);
        let (jres, jids) = jit_probe(probe, idx);
        assert_eq!(
            nids.flags, expect_flags[idx as usize],
            "phase {idx} `{label}`: native flags drifted from the pinned expectation"
        );
        assert_eq!(
            nids.flags, jids.flags,
            "phase {idx} `{label}`: flags native != JIT"
        );
        assert_eq!(
            nids.id0, jids.id0,
            "phase {idx} `{label}`: id0 native != JIT"
        );
        assert_eq!(
            nids.guard_trips, jids.guard_trips,
            "phase {idx} `{label}`: guard_trips native != JIT"
        );
        match (&nres, &jres) {
            (Ok(ne), Ok(je)) => assert!(
                deep_eq_nj(ne, je),
                "phase {idx} `{label}`: Ok payload native != JIT (deep, meta-bit-identical)"
            ),
            (Err(ne), Err(je)) => assert!(
                type_error_agrees_nj(ne, je),
                "phase {idx} `{label}`: Err payload native != JIT"
            ),
            _ => panic!("phase {idx} `{label}`: Ok/Err disagreement native vs JIT"),
        }
    }
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 3 — THE R11 28-CASE DECL GATE, RE-RUN THROUGH THE PHASE-COMPLETED
// ENGINE, native == JIT. The four completions are inert on these cases (empty
// registry, no Bool.true / strings) so the R11 verdict pattern MUST reproduce
// EXACTLY: 16 accept / 12 reject; R10 pattern on 0..22; R11 verdicts on 23..27
// (23 REJECT, 24/25/26 ACCEPT, 27 REJECT). The no-regression proof.
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn pc_decl_gate_rerun_differential() {
    let buffer = run_with_watchdog("JIT compile ld_gate_root", move || {
        jit_module(PC_GATE_TRUST_IR, "ld_gate_root closure", &pc_externs())
    });
    let gate: LdGateFn = unsafe { std::mem::transmute(bind(&buffer, "ld_gate_root")) };

    let r10_accepts = [0usize, 4, 6, 7, 11, 12, 16, 17, 18, 19, 20, 21, 22];
    let r11_expect_23_27 = [false, true, true, true, false];
    let mut accepts = 0usize;
    let mut rejects = 0usize;

    for case in 0u64..28 {
        let (nres, nty) = native_gate(case);
        let (jres, jty) = jit_gate(gate, case);
        // verdict native == JIT
        assert_eq!(
            nres.is_ok(),
            jres.is_ok(),
            "gate case {case}: Ok/Err verdict native != JIT"
        );
        // declared-type payload meta-bit-identical native == JIT
        assert!(
            deep_eq_nj(&nty, &jty),
            "gate case {case}: declared-type payload native != JIT (deep)"
        );
        match (&nres, &jres) {
            (Ok(()), Ok(())) => {}
            (Err(ne), Err(je)) => assert!(
                env_error_agrees_nj(ne, je),
                "gate case {case}: Err payload native != JIT (deep)"
            ),
            _ => unreachable!(),
        }
        // R11 verdict pattern preserved (no regression from the completions)
        let verdict = nres.is_ok();
        if verdict {
            accepts += 1;
        } else {
            rejects += 1;
        }
        let expect_accept = if case < 23 {
            r10_accepts.contains(&(case as usize))
        } else {
            r11_expect_23_27[(case - 23) as usize]
        };
        assert_eq!(
            verdict, expect_accept,
            "gate case {case}: R11 verdict NOT reproduced after phase completion"
        );
    }
    assert_eq!(
        (accepts, rejects),
        (16, 12),
        "gate accept/reject totals drifted"
    );
}

// ════════════════════════════════════════════════════════════════════════════
// TEST 4 — ARMED GOLDEN CORRUPTION: the differential is genuinely sensitive.
// Corrupting the single anon-hash seed (name_anon, `1723`) in the JIT module
// text shifts every JIT-built Name's cached_hash — so the struct-eta payload's
// meta words (compute_meta over the Const/Proj names) DIVERGE from native and
// the deep differential MUST trip. Uncorrupted native == JIT first (baseline).
// ════════════════════════════════════════════════════════════════════════════

#[test]
fn pc_armed_corruption_control() {
    let (nres, _n) = native_probe(0);
    // baseline: native == JIT on the uncorrupted module.
    let good = run_with_watchdog("JIT compile pc_probe_root (baseline)", move || {
        jit_module(PC_PROBE_TRUST_IR, "pc_probe_root closure", &pc_externs())
    });
    let probe_good: PcProbeFn = unsafe { std::mem::transmute(bind(&good, "pc_probe_root")) };
    let (jres_good, _) = jit_probe(probe_good, 0);
    match (&nres, &jres_good) {
        (Ok(ne), Ok(je)) => assert!(deep_eq_nj(ne, je), "baseline: native must == JIT"),
        _ => panic!("baseline: Ok expected"),
    }
    // ARMED: the seed occurs exactly once (name_anon); corrupt it.
    assert_eq!(
        PC_PROBE_TRUST_IR.matches("const u64 1723").count(),
        1,
        "the anon-hash seed must appear exactly once (name_anon)"
    );
    let corrupted = PC_PROBE_TRUST_IR.replacen("const u64 1723", "const u64 1724", 1);
    let bad = run_with_watchdog("JIT compile pc_probe_root (corrupted)", move || {
        jit_module(&corrupted, "pc_probe_root (corrupted)", &pc_externs())
    });
    let probe_bad: PcProbeFn = unsafe { std::mem::transmute(bind(&bad, "pc_probe_root")) };
    let (jres_bad, _) = jit_probe(probe_bad, 0);
    match (&nres, &jres_bad) {
        (Ok(ne), Ok(je)) => assert!(
            !deep_eq_nj(ne, je),
            "ARMED CONTROL FAILED: corrupting the anon seed did NOT diverge the differential"
        ),
        _ => panic!("armed: Ok expected"),
    }
}
